  function modal(title,description,body,submit,onSubmit,drawer){
    const active=document.querySelector('.growth-dialog');if(active)active.close();
    const previous=document.activeElement;
    const d=document.createElement('dialog');d.className='growth-dialog'+(drawer?' growth-detail':'');
    d.setAttribute('aria-labelledby','workflow-title');
    d.innerHTML='<form><div class="growth-modal-head"><div><h2 id="workflow-title">'+esc(title)+'</h2><p>'+esc(description)+'</p></div><button type="button" class="growth-modal-close" aria-label="关闭" data-close-modal>×</button></div>'+body+'<p class="growth-form-error" role="alert" hidden></p><div class="growth-modal-actions"><button type="button" class="growth-btn" data-close-modal>取消</button><button class="growth-btn primary" type="submit">'+esc(submit)+'</button></div></form>';
    document.body.appendChild(d);
    d.querySelectorAll('[data-close-modal]').forEach(function(b){b.onclick=function(){d.close()}});
    d.addEventListener('close',function(){d.remove();if(previous&&previous.isConnected)previous.focus()});
    d.querySelector('form').onsubmit=function(e){e.preventDefault();const values=Object.fromEntries(new FormData(e.target));if('title' in values&&!values.title.trim()){const error=d.querySelector('.growth-form-error');error.textContent='请填写标题，不能只输入空格。';error.hidden=false;d.querySelector('[name="title"]').focus();return}if(onSubmit(values,d)!==false)d.close()};
    d.showModal();
    const field=d.querySelector('[name="title"]');if(field)field.focus();
    return d;
  }
