    if(task)body+='<div class="growth-form-row">'+formSelect('priority','优先级',[['high','高'],['medium','中'],['low','低']],'medium')+formField('dueAt','截止日期',today,'date')+'</div>'+formText('notes','执行说明','');
    else body+=formSelect('category','分类',[['运营经验','运营经验'],['教程','教程'],['职场','职场'],['效率工具','效率工具'],['生活','生活'],['复盘','复盘']],'运营经验')+formText(idea?'description':'body',idea?'切入角度与素材':'内容正文','');
