      if(task){const t=createTask({title:v.title.trim(),priority:v.priority,dueAt:v.dueAt||today,source:'manual',notes:v.notes});if(!t)return false;ui.page='tasks';ui.taskQuery='';ui.taskStatus='all';ui.taskPriority='all';ui.taskSource='all';ui.weekDate=''}
      else if(idea){store.ideas.unshift({id:uid('idea'),title:v.title.trim(),category:v.category,description:v.description,score:80});ui.page='ideas';ui.ideaQuery='';save()}
      else{store.contents.unshift({id:uid('content'),title:v.title.trim(),category:v.category,body:v.body,publishedAt:today,status:'draft',views:0,likes:0,saves:0,comments:0,rate:0});ui.page='content';ui.contentStatus='all';ui.contentCategory='all';ui.contentQuery='';save()}
